#!/usr/bin/python3
from pwn import *

# Connect to the server
conn = remote('mandf.csaw.io', 3000)

# Our sequence
sequence = [-1, -2, -3, -4, -5, -6, -6, -5, -4, -3, -2, -1, -1, -2, -3, -4, -5, -6, -6, -5, -4, -3, -2, -1, -1, -2, -3, -4, -5, -6]

# Receive initial prompt
print(conn.recvuntil(b'Enter your input:').decode())

# Send each number followed by a newline
for num in sequence:
    conn.sendline(str(num).encode())
    print(f"Sent: {num}")
    try:
        # Try to receive any immediate response
        response = conn.recv(timeout=1)
        if response:
            print(f"Response: {response.decode()}")
    except:
        pass

# Get final response
try:
    while True:
        response = conn.recv(timeout=2)
        if not response:
            break
        print("Final response:", response.decode())
except:
    pass

conn.close()

